// Per profile: q, q' = -q^-1 mod 2^32, root 1 of each direction, base row of each root-pack segment.
module ntt_core_consts (
    input  wire [1:0]  profile,
    input  wire        inverse,
    output reg  [31:0] q, qinv, root1,
    output reg  [8:0]  pbase
);
    always @* begin
        q = 32'd0; qinv = 32'd0; root1 = 32'd0; pbase = 9'd0;
        case ({profile, inverse})
            3'b000: begin q = 32'd12289; qinv = 32'd4143984639; root1 = 32'd11183; pbase = 9'd0; end
            3'b001: begin q = 32'd12289; qinv = 32'd4143984639; root1 = 32'd553; pbase = 9'd128; end
            3'b010: begin q = 32'd3329; qinv = 32'd2488732927; root1 = 32'd2379; pbase = 9'd256; end
            3'b011: begin q = 32'd3329; qinv = 32'd2488732927; root1 = 32'd475; pbase = 9'd288; end
            3'b100: begin q = 32'd8380417; qinv = 32'd4236238847; root1 = 32'd25847; pbase = 9'd320; end
            3'b101: begin q = 32'd8380417; qinv = 32'd4236238847; root1 = 32'd4177285; pbase = 9'd352; end
            default: ;
        endcase
    end
endmodule

// FFT timing (model/fft_core_sched.py, model/fft_wide_sched.py): data read offset of the format; per tile, the
// cycle after a butterfly's issue of the tile's root address stage (format 0: 1 + (t >> 2) mod 3; formats 1, 2:
// D + k - lead of the block - 1, k = limb of the tile).
module ntt_core_fft_timing (
    input  wire [1:0]       fmt,
    output reg  [3:0]       d,
    output reg  [16*4-1:0]  droot
);
    always @* begin
        case (fmt)
            2'd0: begin d = 4'd4; droot = 64'h1111333322221111; end
            2'd1: begin d = 4'd3; droot = 64'h4343212143432121; end
            2'd2: begin d = 4'd5; droot = 64'h4321876543218765; end
            default: begin d = 4'd0; droot = 64'd0; end
        endcase
    end
endmodule

